CREATE TABLE `shop_order_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `no` varchar(45) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `amount` decimal(8,2) DEFAULT NULL COMMENT '璁㈠崟閲戦',
  `product_total_amount` decimal(8,2) DEFAULT NULL COMMENT '鍟嗗搧鎬婚噾棰?,
  `delivery_fee` decimal(8,2) DEFAULT NULL COMMENT '杩愯垂',
  `discount_amount` decimal(8,2) DEFAULT NULL COMMENT '浼樻儬閲戦',
  `status` tinyint(4) DEFAULT NULL COMMENT '璁㈠崟鐘舵€?0:寰呭鐞?20:宸插畬鎴?30:璁㈠崟鍙栨秷;frontType:select',
  `pay_status` tinyint(4) DEFAULT NULL COMMENT '鏀粯鐘舵€?0:寰呮敮浠?1:宸叉敮浠?frontType:select',
  `freight_status` tinyint(4) DEFAULT NULL COMMENT '璐ц繍鐘舵€?0:寰呭鐞?10:宸插彂璐?20:宸叉敹璐?frontType:select',
  `receiving_address` varchar(500) DEFAULT NULL COMMENT '鏀惰揣鍦板潃',
  `consignee` varchar(45) DEFAULT NULL COMMENT '鏀惰揣浜?,
  `receiving_phone_number` varchar(45) DEFAULT NULL COMMENT '鏀惰揣鎵嬫満鍙?,
  `order_type` tinyint(4) DEFAULT NULL COMMENT '璁㈠崟绫诲瀷;1:瀹炵墿璁㈠崟,10:铏氭嫙璁㈠崟,20:鏈嶅姟璁㈠崟;frontType:select',
  `source` tinyint(4) DEFAULT NULL COMMENT '璁㈠崟鏉ユ簮;1:WAP,10:灏忕▼搴?20:鍏紬鍙?30:WEB,40:APP;frontType:select',
  `remark` varchar(1000) DEFAULT NULL COMMENT '澶囨敞',
  `updated_time` datetime DEFAULT NULL COMMENT '鏇存柊鏃堕棿',
  `created_time` datetime DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8 COMMENT='璁㈠崟';
