  `model_id` int(11) DEFAULT NULL COMMENT ';;editRequired:undefined',
  `created_time` datetime DEFAULT NULL,
  `updated_time` datetime DEFAULT NULL COMMENT '妯″瀷ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COMMENT='鍟嗗搧鍒嗙被;;foreign:,frontHome:tree,tree:id~name~parent_id,apis:guest/guest_id.details/list/batch/create/update/delete/option/exportExcel/importExcel~admin/admin_id.details/list/batch/create/update/delete/option/exportExcel/importExcel';
