/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shop_product_spec_value` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) DEFAULT NULL COMMENT '浜у搧ID',
  `sku_id` int(11) DEFAULT 0 COMMENT 'SKU ID',
  `spec_id` int(11) DEFAULT NULL COMMENT '瑙勬牸ID',
  `sort_order` int(11) DEFAULT NULL COMMENT '鎺掑簭',
  `value` varchar(50) DEFAULT NULL COMMENT '瑙勬牸鍊?,
  `extend` varchar(255) DEFAULT NULL COMMENT '鎵╁睍鏁版嵁',
  `updated_time` datetime DEFAULT NULL COMMENT '鏇存柊鏃堕棿',
  `created_time` datetime DEFAULT NULL COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`),
  UNIQUE KEY `index2` (`product_id`,`sku_id`,`spec_id`)
) ENGINE=InnoDB AUTO_INCREMENT=312 DEFAULT CHARSET=utf8 COMMENT='鍟嗗搧瑙勬牸鍊?;
